@kt.kernel
def k(x=kt.In(8, 32), qa=kt.Out(8, 32, dtype="mx7a", layout={"gm": 1, "nk": 1})):
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(1):
            r = c * 4 + t * 4
            v = kt.unpack(kt.load(x[r : r + 4, :], gt4=True))
            kt.store(qa[r : r + 4, :], kt.pack(v, "mx7a"))
